CREATE TABLE users(id text PRIMARY KEY,name text NOT NULL,email text NOT NULL UNIQUE,email_verified boolean NOT NULL DEFAULT false,image text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),phone_number text NOT NULL UNIQUE,phone_verified boolean NOT NULL DEFAULT false,policy_version text NOT NULL,policy_accepted_at timestamptz NOT NULL,referral_code text NOT NULL UNIQUE,invited_by text REFERENCES users(id),role text NOT NULL DEFAULT 'customer' CHECK(role IN ('customer','admin')),permissions jsonb NOT NULL DEFAULT '[]',two_factor_enabled boolean DEFAULT false);
CREATE TABLE sessions(id text PRIMARY KEY,expires_at timestamptz NOT NULL,token text NOT NULL UNIQUE,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),ip_address text,user_agent text,user_id text NOT NULL REFERENCES users(id) ON DELETE CASCADE);
CREATE INDEX sessions_user ON sessions(user_id);
CREATE TABLE auth_accounts(id text PRIMARY KEY,account_id text NOT NULL,provider_id text NOT NULL,user_id text NOT NULL REFERENCES users(id) ON DELETE CASCADE,access_token text,refresh_token text,id_token text,access_token_expires_at timestamptz,refresh_token_expires_at timestamptz,scope text,password text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE verifications(id text PRIMARY KEY,identifier text NOT NULL,value text NOT NULL,expires_at timestamptz NOT NULL,created_at timestamptz DEFAULT now(),updated_at timestamptz DEFAULT now());
CREATE INDEX verification_identifier ON verifications(identifier);
CREATE TABLE two_factors(id text PRIMARY KEY,secret text NOT NULL,backup_codes text NOT NULL,user_id text NOT NULL REFERENCES users(id),verified boolean DEFAULT false);
CREATE TABLE ledger_accounts(id text PRIMARY KEY,user_id text REFERENCES users(id),bucket text NOT NULL CHECK(bucket IN ('available','reserved','rewards','clearing','revenue','reward_expense','reward_debt')),balance bigint NOT NULL DEFAULT 0,allow_negative boolean NOT NULL DEFAULT false,CHECK(allow_negative OR balance>=0),UNIQUE(user_id,bucket));
CREATE TABLE journals(id text PRIMARY KEY,reference text NOT NULL UNIQUE,reason text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE ledger_entries(id bigserial PRIMARY KEY,journal_id text NOT NULL REFERENCES journals(id),account_id text NOT NULL REFERENCES ledger_accounts(id),amount bigint NOT NULL CHECK(amount<>0),created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX entries_account ON ledger_entries(account_id);
CREATE FUNCTION immutable_record() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Financial history is immutable'; END $$;
CREATE TRIGGER immutable_journal BEFORE UPDATE OR DELETE ON journals FOR EACH ROW EXECUTE FUNCTION immutable_record();
CREATE TRIGGER immutable_entry BEFORE UPDATE OR DELETE ON ledger_entries FOR EACH ROW EXECUTE FUNCTION immutable_record();
CREATE FUNCTION balanced_journal() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF (SELECT count(*)<2 OR coalesce(sum(amount),0)<>0 FROM ledger_entries WHERE journal_id=NEW.id) THEN RAISE EXCEPTION 'Unbalanced journal'; END IF; RETURN NEW; END $$;
CREATE CONSTRAINT TRIGGER balanced_journal_check AFTER INSERT ON journals DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION balanced_journal();
CREATE FUNCTION apply_ledger_entry() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN UPDATE ledger_accounts SET balance=balance+NEW.amount WHERE id=NEW.account_id; RETURN NEW; END $$;
CREATE TRIGGER apply_entry AFTER INSERT ON ledger_entries FOR EACH ROW EXECUTE FUNCTION apply_ledger_entry();
CREATE TABLE transactions(id text PRIMARY KEY,user_id text NOT NULL REFERENCES users(id),kind text NOT NULL CHECK(kind IN ('deposit','withdrawal','payment','gift_sale','gift_purchase','reward_claim','adjustment')),status text NOT NULL DEFAULT 'created' CHECK(status IN ('created','awaiting_authorization','processing','successful','failed','reversed','cancelled')),amount bigint NOT NULL CHECK(amount>0),fee bigint NOT NULL DEFAULT 0 CHECK(fee>=0),currency text NOT NULL DEFAULT 'NGN' CHECK(currency='NGN'),reference text NOT NULL UNIQUE,provider text,provider_reference text,service_id text,idempotency_key text NOT NULL,request_hash text NOT NULL,details jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(user_id,idempotency_key));
CREATE INDEX transactions_user_date ON transactions(user_id,created_at DESC);
CREATE TABLE service_catalog(id text PRIMARY KEY,name text NOT NULL,category text NOT NULL,provider text NOT NULL,enabled boolean NOT NULL DEFAULT false,logo text,min bigint NOT NULL CHECK(min>0),max bigint NOT NULL,fee bigint NOT NULL DEFAULT 0 CHECK(fee>=0),requires_validation boolean NOT NULL DEFAULT false,CHECK(max>=min));
CREATE TABLE jobs(id text PRIMARY KEY,type text NOT NULL,payload jsonb NOT NULL,dedupe text NOT NULL UNIQUE,status text NOT NULL DEFAULT 'queued',attempts int NOT NULL DEFAULT 0,run_at timestamptz NOT NULL DEFAULT now(),lease_until timestamptz,lease_token text,last_error text,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX jobs_ready ON jobs(status,run_at);
CREATE TABLE webhook_events(id text PRIMARY KEY,provider text NOT NULL,event_key text NOT NULL,payload jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(provider,event_key));
CREATE TABLE reward_rules(id text PRIMARY KEY,version int NOT NULL UNIQUE,rule jsonb NOT NULL,created_by text NOT NULL REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now());
CREATE TRIGGER immutable_reward_rule BEFORE UPDATE OR DELETE ON reward_rules FOR EACH ROW EXECUTE FUNCTION immutable_record();
CREATE TABLE rewards(id text PRIMARY KEY,user_id text NOT NULL REFERENCES users(id),referred_user_id text NOT NULL REFERENCES users(id),transaction_id text NOT NULL REFERENCES transactions(id),rule_id text NOT NULL REFERENCES reward_rules(id),amount bigint NOT NULL CHECK(amount>0),status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','available','claimed','reversed')),available_at timestamptz NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(user_id,transaction_id));
CREATE INDEX rewards_user ON rewards(user_id);
CREATE TABLE notifications(id text PRIMARY KEY,user_id text NOT NULL REFERENCES users(id),title text NOT NULL,body text NOT NULL,read boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE beneficiaries(id text PRIMARY KEY,user_id text NOT NULL REFERENCES users(id),name text NOT NULL,kind text NOT NULL,details jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE support_requests(id text PRIMARY KEY,user_id text NOT NULL REFERENCES users(id),subject text NOT NULL,message text NOT NULL,transaction_id text REFERENCES transactions(id),status text NOT NULL DEFAULT 'open',response text,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE audit_events(id text PRIMARY KEY,actor_id text REFERENCES users(id),action text NOT NULL,resource text NOT NULL,before_value jsonb,after_value jsonb,correlation_id text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TRIGGER immutable_audit BEFORE UPDATE OR DELETE ON audit_events FOR EACH ROW EXECUTE FUNCTION immutable_record();
CREATE TABLE beneficiary_validations(id text PRIMARY KEY,user_id text NOT NULL REFERENCES users(id),kind text NOT NULL,destination_hash text NOT NULL,result jsonb NOT NULL,expires_at timestamptz NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE gift_products(id text PRIMARY KEY,brand text NOT NULL,region text NOT NULL,card_type text NOT NULL,enabled boolean NOT NULL DEFAULT false,buy_enabled boolean NOT NULL DEFAULT false,sell_enabled boolean NOT NULL DEFAULT false,rate_kobo bigint NOT NULL CHECK(rate_kobo>0),min_units bigint NOT NULL,max_units bigint NOT NULL,version int NOT NULL DEFAULT 1);
CREATE TABLE gift_quotes(id text PRIMARY KEY,user_id text NOT NULL REFERENCES users(id),product_id text NOT NULL REFERENCES gift_products(id),product_version int NOT NULL,units bigint NOT NULL,amount bigint NOT NULL,expires_at timestamptz NOT NULL,used boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE evidence(id text PRIMARY KEY,user_id text NOT NULL REFERENCES users(id),file_path text NOT NULL,mime text NOT NULL,size int NOT NULL,status text NOT NULL DEFAULT 'quarantined',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE gift_sales(id text PRIMARY KEY,user_id text NOT NULL REFERENCES users(id),quote_id text NOT NULL UNIQUE REFERENCES gift_quotes(id),evidence_id text NOT NULL REFERENCES evidence(id),status text NOT NULL DEFAULT 'review',reason text,settlement_reference text,reviewed_by text REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE exchange_pairs(id text PRIMARY KEY,source text NOT NULL,target text NOT NULL,enabled boolean NOT NULL DEFAULT false,provider text NOT NULL,quote_rules jsonb NOT NULL,settlement_rules jsonb NOT NULL);
CREATE TABLE rate_limits(key text PRIMARY KEY,count int NOT NULL,reset_at timestamptz NOT NULL);
CREATE TABLE phone_challenges(id text PRIMARY KEY,user_id text NOT NULL REFERENCES users(id),code_hash text NOT NULL,expires_at timestamptz NOT NULL,attempts int NOT NULL DEFAULT 0);
INSERT INTO ledger_accounts(id,bucket,allow_negative) VALUES('platform:clearing','clearing',true),('platform:revenue','revenue',true),('platform:reward_expense','reward_expense',true);
